/** Keys generated by uploads; external URLs and static assets are not storage keys. */
export function isUploadKey(value: string): boolean {
    const segments = value.split("/")
    return (
        segments[0] === "uploads" &&
        segments.length > 1 &&
        segments.every(
            (segment) =>
                segment !== "" &&
                segment !== "." &&
                segment !== ".." &&
                !/[\\\u0000-\u001f\u007f]/.test(segment),
        )
    )
}

/** Resolve stored keys at request time without exposing storage configuration to clients. */
export function getImageUrl(path: string): string {
    return isUploadKey(path)
        ? `/api/images/${path.split("/").map(encodeURIComponent).join("/")}`
        : path
}
